        progress = easeInOutQuad(progress);
        this.renderer.setPan(
          panX + (X - panX) * progress,
          panY + (Y - panY) * progress
        );
        this.renderer.changed();
        if (progress < 1) {
          this.requestFrame(animate);
        } else {
          this.renderer.setPan(X, Y);
          this.renderer.changed();
        }
