  async function showProRuntimeDiagnostics(pro, preferenceWindow) {
    const results = await runProRuntimeDiagnostics(pro);
    const lines = results.map(formatDiagnosticResult);
    const passed = results.filter((result) => result.status === "pass").length;
    const failed = results.filter((result) => result.status === "fail").length;
    const skipped = results.filter((result) => result.status === "skip").length;
    const summary = getString("pro-diagnostics-summary", {
      args: { passed, failed, skipped }
    });
    ztoolkit.log(summary, ...lines);
    if (!preferenceWindow.closed) {
      preferenceWindow.alert(`${summary}

${lines.join("\n")}`);
    }
  }
