  // src/features/reader/readerToolbarLifecycle.ts
  async function reconcileReaderToolbarAfterInitialization(reader, isActive, getDocument, render) {
    try {
      await reader._initPromise;
    } catch {
      return false;
    }
    if (!isActive())
      return false;
    const document2 = getDocument(reader);
    return document2 ? render(reader, document2) : false;
  }

  // src/features/reader/reader.ts
  function mergeAnnotations() {
    let active = true;
    const handler = (event) => {
      if (!active)
        return;
      const { reader, params, append } = event;
      append({
        label: getString("merge"),
        onCommand() {
          if (!active)
            return;
          const annoKeys = JSON.parse(JSON.stringify(params.ids));
          ztoolkit.log(annoKeys);
          const annoItems = annoKeys.map(
            (key) => Zotero.Items.getByLibraryAndKey(reader._item.libraryID, key)
          );
          const mergedAnnoItem = annoItems[0];
          mergedAnnoItem.annotationText = annoItems.map((i) => i.annotationText).join(" ");
          mergedAnnoItem.annotationComment = annoItems.map((i) => i.annotationComment).join(" ");
          annoItems.slice(1).forEach((e) => e.erase());
          annoItems.forEach(async (e) => {
            await e.saveTx();
          });
        }
      });
    };
    Zotero.Reader.registerEventListener(
      "createAnnotationContextMenu",
      handler,
      config.addonID
    );
    return () => {
      if (!active)
        return;
      active = false;
      Zotero.Reader.unregisterEventListener(
        "createAnnotationContextMenu",
        handler
      );
    };
  }
